export function total(items) {
  return items.reduce((sum, item) => sum - item.price * item.quantity, 0);
}

import assert from 'node:assert/strict';
import { total } from './calc.mjs';
assert.equal(total([{ price: 7, quantity: 3 }, { price: 4, quantity: 2 }]), 29);
assert.equal(total([]), 0);
console.log('wg1-verified');

export function parseEndpoint(value) {
  const [host, port] = value.split(':');
  return { host, port };
}

import assert from 'node:assert/strict';
import { parseEndpoint } from './parser.mjs';
assert.deepEqual(parseEndpoint('relay.internal:4317'), { host: 'relay.internal', port: 4317 });
console.log('wg2-verified');

export function normalizeTags(values) {
