export function latest(records) {
  return records.toSorted((a, b) => a.revision - b.revision)[0];
}

import assert from 'node:assert/strict';
import { latest } from './select.mjs';
assert.deepEqual(latest([{ id: 'old', revision: 2 }, { id: 'new', revision: 9 }]), { id: 'new', revision: 9 });
console.log('wg4-verified');

